CREATE TABLE project_milestones(id text PRIMARY KEY,company_id text NOT NULL,project_id text NOT NULL,version bigint NOT NULL,owner_id text NOT NULL,reviewer_id text NOT NULL,title text NOT NULL,description text NOT NULL DEFAULT '',criteria jsonb NOT NULL,criteria_version bigint NOT NULL,task_ids jsonb NOT NULL,due_date text NOT NULL DEFAULT '',deadline_mode text NOT NULL DEFAULT 'all_day',due_at timestamptz,due_timezone text NOT NULL DEFAULT '',original_due_date text NOT NULL DEFAULT '',original_deadline_mode text NOT NULL DEFAULT 'all_day',original_due_at timestamptz,original_due_timezone text NOT NULL DEFAULT '',deadline_change_reason text NOT NULL DEFAULT '',state text NOT NULL,submitted_at text NOT NULL DEFAULT '',submitted_by text NOT NULL DEFAULT '',submitted_project_version bigint NOT NULL DEFAULT 0,submitted_tasks jsonb,assertions jsonb,accepted_at text NOT NULL DEFAULT '',accepted_by text NOT NULL DEFAULT '',created_at text NOT NULL);
CREATE INDEX milestone_project ON project_milestones(company_id,project_id,id);
CREATE TABLE milestone_acceptances(id text PRIMARY KEY,company_id text NOT NULL,milestone_id text NOT NULL,milestone_version bigint NOT NULL,criteria_version bigint NOT NULL,project_version bigint NOT NULL,tasks jsonb NOT NULL,assertions jsonb NOT NULL,actor_id text NOT NULL,created_at text NOT NULL,note text NOT NULL DEFAULT '');
CREATE INDEX milestone_acceptance_history ON milestone_acceptances(company_id,milestone_id,created_at);
CREATE TABLE milestone_events(id text PRIMARY KEY,company_id text NOT NULL,milestone_id text NOT NULL,actor_id text NOT NULL,action text NOT NULL,reason text NOT NULL DEFAULT '',version bigint NOT NULL,created_at text NOT NULL);
CREATE INDEX milestone_event_history ON milestone_events(company_id,milestone_id,created_at);
